// src/app/api/withdraw/route.ts
import { findCurrentUser } from "@/data/user";
import { INTERNAL_SERVER_ERROR } from "@/error";
import { db } from "@/lib/db";
import { NextRequest, NextResponse } from "next/server";
import { Prisma } from "@prisma/client";
import { createNotification } from "@/action/notifications";

export const POST = async (req: NextRequest) => {
  try {
    const { account_number, amount, ps, note } = await req.json();

    // Validate required fields
    if (!account_number || !amount || !ps) {
      return NextResponse.json({
        success: false,
        message: "Missing required fields: account_number, amount, and ps are required"
      }, { status: 400 });
    }

    const user: any = await findCurrentUser();
    if (!user)
      return NextResponse.json({ success: false, message: "Authentication failed" }, { status: 401 });

    const wallet = await db.wallet.findUnique({ where: { userId: user.id } });
    if (!wallet || parseFloat(wallet.balance.toString()) < parseFloat(amount)) {
      return NextResponse.json({ success: false, message: "Insufficient balance" }, { status: 400 });
    }

    // Generate a manual invoice number
    const invoice_no = `MANUAL-${Date.now()}`;

    // DB update (manual withdraw)
    await db.withdraw.create({
      data: {
        amount: new Prisma.Decimal(amount),
        cardId: account_number, // যদি cardId থাকে, না হলে অন্য column ব্যবহার করতে পারেন
        status: "PENDING",      // admin later approve
        user: { connect: { id: user.id } },
        createdAt: new Date(),
      },
    });

    // Decrement wallet balance immediately (optional)
    await db.wallet.update({
      where: { userId: user.id },
      data: { balance: { decrement: amount } },
    });

    // Notification
    await createNotification({
      title: "Manual Withdraw Initiated",
      description: `Your withdraw of ${amount} BDT has been noted. ${note || ""}`,
      userId: user.id,
      icon: "MONEY",
    });

    return NextResponse.json({
      success: true,
      payload: { invoice_no },
    }, { status: 200 });

  } catch (error) {
    console.error("Manual Withdraw error:", error);
    return NextResponse.json({ success: false, message: INTERNAL_SERVER_ERROR }, { status: 500 });
  }
};
